```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name IN ('RoutePlanController.getQuickestRoutes','RoutePlanController.getCheapestRoutes','RoutePlanController.getMinStopStations') GROUP BY 1,2,3 ORDER BY 2", "claim": "getQuickestRoutes and getCheapestRoutes p95 rose to about 1860 ms while getMinStopStations stayed about 23 ms."},
        {"kind": "trace", "sql": "SELECT span_name, COUNT(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM normal_traces WHERE service_name='ts-route-plan-service' AND span_name IN ('RoutePlanController.getQuickestRoutes','RoutePlanController.getCheapestRoutes') GROUP BY 1 ORDER BY 1", "claim": "In the normal period the same route-plan methods ran at about 74-82 ms p95."},
        {"kind": "trace", "sql": "WITH ri AS (SELECT trace_id, span_id, span_name, duration FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' AND span_name LIKE 'RoutePlanController.get%Routes'), rc AS (SELECT trace_id, parent_span_id, SUM(duration) kids FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' GROUP BY 1,2) SELECT ri.span_name, COUNT(*) n, approx_quantile(ri.duration - COALESCE(rc.kids,0),0.5)/1e6 p50_self_ms FROM ri LEFT JOIN rc ON rc.trace_id=ri.trace_id AND rc.parent_span_id=ri.span_id GROUP BY 1", "claim": "Self time of these route-plan methods, excluding its client calls, is about 1820 ms, so the delay is inside the process."},
        {"kind": "metric", "sql": "SELECT metric, AVG(value) avg_v, MAX(value) max_v FROM abnormal_metrics WHERE service_name='ts-route-plan-service' AND metric IN ('k8s.pod.cpu.usage','container.cpu.usage','k8s.pod.memory_limit_utilization') GROUP BY 1", "claim": "Route-plan CPU and memory stayed low or lower than normal, so the slowness is not resource exhaustion."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, c.span_name, COUNT(*) n, approx_quantile(c.duration,0.5)/1e6 p50_ms, approx_quantile(c.duration,0.95)/1e6 p95_ms FROM abnormal_traces c WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND c.span_name='POST' GROUP BY 1,2", "claim": "Travel-plan's client POST calls to route-plan now take about 1856 ms at p50, matching route-plan's slow methods."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name IN ('POST /api/v1/travelplanservice/travelPlan/quickest','POST /api/v1/travelplanservice/travelPlan/cheapest') GROUP BY 1,2", "claim": "User-facing travelPlan quickest and cheapest requests at ui-dashboard now take about 1866 ms p95, with no errors."}
      ]
    }
  ]
}
```

